{"function":"() => {
const sel = el => { if (el.id) return '#'+CSS.escape(el.id); let p=[]; while(el && el.nodeType===1 && el!==document.body){ let s=el.tagName.toLowerCase(); if(el.id){p.unshift('#'+CSS.escape(el.id));break;} const sib=[...el.parentNode.children].filter(c=>c.tagName===el.tagName); if(sib.length>1) s+=':nth-of-type('+(sib.indexOf(el)+1)+')'; p.unshift(s); el=el.parentElement;} return p.join('>'); };
const r = {};
r.headings = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6,[role=heading]')].map(h=>h.tagName+':'+h.textContent.trim().slice(0,50));
r.landmarks = [...document.querySelectorAll('header,nav,main,footer,aside,[role]')].map(e=>e.tagName+'['+(e.getAttribute('role')||'')+'] '+(e.getAttribute('aria-label')||'')+' '+e.className.toString().slice(0,60));
r.skip = [...document.querySelectorAll('a')].slice(0,5).map(a=>a.outerHTML.slice(0,150));
r.inputs = [...document.querySelectorAll('input,select,textarea')].map(i=>({s:sel(i),type:i.type,id:i.id,name:i.name,al:i.getAttribute('aria-label'),alb:i.getAttribute('aria-labelledby'),lab:i.labels?[...i.labels].map(l=>l.textContent.trim()):null,ph:i.placeholder, ro:i.readOnly}));
r.buttons = [...document.querySelectorAll('button,[role=button]')].filter(b=>!(b.textContent.trim()||b.getAttribute('aria-label')||b.title)).map(b=>sel(b)+' '+b.outerHTML.slice(0,200));
r.clickDivs = [...document.querySelectorAll('div,span')].filter(e=>getComputedStyle(e).cursor==='pointer' && !e.closest('button,a') && e.querySelector('button,a,input')===null).slice(0,20).map(e=>sel(e)+' tab='+e.getAttribute('tabindex')+' role='+e.getAttribute('role')+' '+e.outerHTML.slice(0,200));
return r;
}"}

{"function":"() => {
